SELECT w.id, w.biz_no AS bizNo, w.user_id AS userId, u.nickname, u.email, w.amount, w.account, w.name, w.status, w.processed_at AS processedAt, w.processed_by AS processedBy, w.result_remark AS resultRemark, w.created_at AS createdAt FROM u_withdraw_request w LEFT JOIN u_user u ON u.id = w.user_id AND u.is_deleted = 0 WHERE w.is_deleted = 0
AND w.user_id = #{userId}
AND w.biz_no = #{bizNo}
AND w.status = #{status}
ORDER BY w.created_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM u_withdraw_request w
WHERE w.is_deleted = 0

    AND w.user_id = #{userId}


    AND w.biz_no = #{bizNo}


    AND w.status = #{status}
